reg('skytools4','Sky Observation Tools','하늘 관찰 도구','S4E1.a',(i,lv)=>evidence(tools,i,lv,B('Which observing choice is supported?','관찰에 알맞은 선택을 골라요.')));
reg('starplanet4','Stars and Planets','별과 행성','S4E1.b–c',(i,lv)=>{
 const stars=[['Sun|태양','It produces its own light.|스스로 빛을 내요.'],['Earth|지구','It orbits the Sun and reflects sunlight.|태양을 돌고 햇빛을 반사해요.'],['Mars|화성','It orbits the Sun and reflects incoming light.|태양을 돌며 받은 빛을 반사해요.'],['Sirius|시리우스','It produces its own light.|스스로 빛을 내요.'],['Venus|금성','It reflects sunlight.|햇빛을 반사해요.'],['Jupiter|목성','It orbits the Sun and reflects sunlight.|태양을 돌고 햇빛을 반사해요.'],['Object A|천체 가','It releases energy and light.|에너지와 빛을 내보내요.'],['Saturn|토성','It travels around the Sun.|태양 주위를 돌아요.'],['Object B|천체 나','It shines with its own emitted light.|스스로 내는 빛으로 빛나요.'],['Neptune|해왕성','It orbits a star and reflects its light.|별을 돌며 그 빛을 반사해요.']];
 if(lv===1){const r=stars[i],isStar=[0,3,6,8].includes(i);return q(B('Use the description to classify this object.','설명을 보고 이 천체를 분류해요.'),B(`${b(r[0]).en}: ${b(r[1]).en}`,`${b(r[0]).ko}: ${b(r[1]).ko}`),b(isStar?'Star|별':'Planet|행성'),[b(isStar?'Planet|행성':'Star|별'),b('Unclassified|분류 근거 부족')]);}
 const cases=[['equal light output; A is closer|내는 빛이 같고 가 별이 더 가까워요','A appears brighter|가 별이 더 밝아 보여요'],['equal distance; B emits more light|거리가 같고 나 별이 빛을 더 내요','B appears brighter|나 별이 더 밝아 보여요'],['equal size only; distance unknown|크기만 같고 거리는 몰라요','Need distance and light-output data|거리와 내는 빛 자료가 더 필요해요'],['A larger; distance and output unknown|가 별이 더 크지만 거리와 내는 빛은 몰라요','Size alone is insufficient|크기만으로 판단할 수 없어요'],['equal light output; B is closer|내는 빛이 같고 나 별이 더 가까워요','B appears brighter|나 별이 더 밝아 보여요'],['equal distance; A emits more light|거리가 같고 가 별이 빛을 더 내요','A appears brighter|가 별이 더 밝아 보여요'],['same apparent brightness; actual sizes unknown|보이는 밝기는 같고 실제 크기는 몰라요','Actual sizes need more evidence|실제 크기를 알려면 근거가 더 필요해요'],['one bright photograph; exposure unknown|밝은 사진 한 장인데 노출 조건을 몰라요','Photograph brightness alone is insufficient|사진 밝기만으로 판단할 수 없어요'],['same star viewed with and without thin cloud|같은 별을 옅은 구름이 있을 때와 없을 때 봐요','Viewing conditions can alter appearance|관찰 조건이 보이는 모습을 바꿀 수 있어요'],['near Sun and distant star both emit light|가까운 태양과 먼 별이 모두 빛을 내요','Distance affects their apparent brightness|거리가 보이는 밝기에 영향을 줘요']];const r=cases[i];return q(B('What conclusion follows under these conditions?','이 조건에서 뒷받침되는 결론을 골라요.'),b('Practice comparison: '+r[0].split('|')[0]+'|연습 비교: '+r[0].split('|')[1]),b(r[1]),[b('Size determines brightness|보이는 밝기로 실제 크기를 재요'),b('Brightness ignores distance|보이는 밝기는 거리의 영향을 받지 않아요')]);
});
const planets=['Mercury|수성','Venus|금성','Earth|지구','Mars|화성','Jupiter|목성','Saturn|토성','Uranus|천왕성','Neptune|해왕성'];
reg('solarmodel4','Solar System Models','태양계 모형 검토','S4E1.d',(i,lv)=>{if(lv===1){if(i<8){const p=b(planets[i]);return q(B(`Which planet is number ${i+1} outward from the Sun?`,`태양에서 바깥쪽으로 ${i+1}번째 행성을 골라요.`),B('Order the eight planets; the Sun is not a planet.','행성 여덟 개의 순서를 생각해요. 태양은 행성이 아니에요.'),p,[b(planets[(i+2)%8]),b(planets[(i+4)%8])]);}return q(B('Choose the correct classification.','알맞은 분류를 골라요.'),b(i===8?'Pluto|명왕성':'Mercury, Venus, Earth, Mars|수성, 금성, 지구, 화성'),b(i===8?'Dwarf planet|왜소행성':'Rocky inner planets|안쪽의 암석형 행성'),[b('Light-producing star|스스로 빛을 내는 별'),b('Gas-dominated planet|가스가 주성분인 행성')]);}
 const limits=[['Equal gaps between all planets|행성 사이 간격이 모두 같아요','Actual distances are not shown to scale|실제 거리의 축척을 나타내지 못해요'],['Planet beads all the same size|행성 구슬의 크기가 같아요','Relative planet sizes are missing|행성 크기의 비율이 빠져 있어요'],['Earth bead larger than Jupiter bead|지구 구슬이 목성 구슬보다 커요','The size comparison is incorrect|크기 비교가 잘못되었어요'],['Neptune placed nearest the Sun|해왕성을 태양 바로 옆에 놓아요','The planet order is incorrect|행성 순서가 잘못되었어요'],['Rocky label placed on Jupiter|목성에 암석형이라고 표시해요','The composition label is incorrect|구성 물질 표시가 잘못되었어요'],['Scale distances but oversized planet icons|거리는 축척에 맞지만 행성 그림은 크게 그려요','Distance scale does not imply size scale|거리 축척과 크기 축척을 구별해야 해요'],['A flat picture of a three-dimensional system|입체 태양계를 평면 그림으로 그려요','The model simplifies three dimensions|입체 구조를 간단하게 나타내요'],['Static picture with no orbital motion|공전 움직임이 없는 정지 그림이에요','It cannot directly show motion over time|시간에 따른 움직임을 직접 보여 주지 못해요'],['Sun labeled a planet|태양을 행성이라고 표시해요','The Sun must be classified as a star|태양은 별로 분류해야 해요'],['Only the first four planets drawn|앞쪽 행성 네 개만 그려요','The outer planets are omitted|바깥쪽 행성이 빠져 있어요']];const r=limits[i];return q(B('Identify a limitation of this described model.','이 모형의 한계를 찾아요.'),b(r[0]),b(r[1]),[b(['The planet order is incorrect|행성 순서가 잘못되었어요','The planet order is incorrect|행성 순서가 잘못되었어요','The planet distances need correction|행성 거리를 고쳐야 해요','The planet sizes need correction|행성 크기를 고쳐야 해요','The planet sequence needs correction|행성 순서를 고쳐야 해요','Correct distance scale proves correct size scale|거리 축척이 맞으므로 크기 축척도 맞아요','The model is three-dimensional with smaller planets|작은 행성으로 만든 입체 모형이에요','The picture directly shows a whole orbit over time|그림이 시간에 따른 공전 한 바퀴를 직접 보여요','The Sun label is right; planet sizes need correction|태양 표시는 맞고 행성 크기를 고쳐야 해요','The drawing is complete but the spacing needs correction|빠진 행성은 없고 간격을 고쳐야 해요'][i]),b(['Relative planet sizes, rather than distances, are missing|거리가 아니라 행성 크기 비율이 빠져 있어요','Relative distances, rather than planet sizes, are missing|행성 크기가 아니라 거리 비율이 빠져 있어요','The planet sequence needs correction|행성 순서를 고쳐야 해요','The planet distances need correction|행성 거리를 고쳐야 해요','The planet distances need correction|행성 거리를 고쳐야 해요','Large icons prove large distances|큰 그림이 먼 거리를 증명해요','The picture preserves full depth|그림은 입체의 깊이를 보존해요','Motion can be measured from a single undated picture|날짜 없는 사진 한 장으로 움직임을 잴 수 있어요','The Sun is correctly classified as a planet|태양을 행성으로 분류한 것은 맞아요','The outer planets are included|바깥쪽 행성도 그려져 있어요'][i])]);});
reg('daylight4','Daylight Evidence','낮과 밤의 길이','S4E2.a',(i,lv)=>{const dates=['Jan 15','Feb 15','Mar 15','Apr 15','May 15','Jun 15','Jul 15','Aug 15','Sep 15','Dec 15'],north=[10,11,12,13,14,15,14,13,12,9][i],south=24-north;return lv===1?q(B('How many hours of darkness in this 24-hour model day?','24시간인 모형의 하루에서 어두운 시간은 몇 시간일까요?'),B(`Practice data, northern site, ${dates[i]}: ${north} daylight hours.`,`연습용 가상 자료, 북반구 지점, ${[1,2,3,4,5,6,7,8,9,12][i]}월 15일: 낮 ${north}시간.`),String(24-north),[String(23-north),String(25-north)]):q(B('Compare the modeled daylight at opposite hemispheres.','북반구와 남반구의 낮 길이를 모형 자료로 비교해요.'),B(`Practice data, ${dates[i]}: north ${north} h; south ${south} h.`,`연습용 가상 자료, ${[1,2,3,4,5,6,7,8,9,12][i]}월 15일: 북반구 ${north}시간, 남반구 ${south}시간.`),b(north>south?'North has more daylight|북반구의 낮이 더 길어요':north<south?'South has more daylight|남반구의 낮이 더 길어요':'Equal daylight in this model|이 모형에서는 낮 길이가 같아요'),[b(north>=south?'South has more daylight|남반구의 낮이 더 길어요':'North has more daylight|북반구의 낮이 더 길어요'),b(north===south?'North has more daylight|북반구의 낮이 더 길어요':'Equal daylight in this model|이 모형에서는 낮 길이가 같아요')]);});
