reg('moonphase4','Repeating Moon Phases','달 모습의 반복','S4E2.b',(i,lv)=>{if(lv===1&&i<8){const r=moon[i].map(b);return q(B('Which phase matches the observation?','관찰에 맞는 달 모습은?'),r[0],r[1],shuffle(moon.slice(0,8).filter((_,j)=>j!==i)).slice(0,2).map(row=>b(row[1])));}return evidence(moon,i,lv,B('Which phase or pattern matches the observation?','관찰에 맞는 달 모습이나 규칙을 골라요.'));});
