reg('seasons4','Why Seasons Change','계절의 까닭','S4E2.c',(i,lv)=>evidence(seasons,i,lv,B('Which conclusion fits the model?','모형에 맞는 결론을 골라요.')));
const changes=[['Ice receives energy and becomes liquid.|얼음이 에너지를 받아 액체가 돼요.','Melting|녹음','Energy enters the water.|물에 에너지가 들어와요.'],['Liquid water loses energy and becomes ice.|액체 물이 에너지를 잃고 얼음이 돼요.','Freezing|얼음으로 굳음','Energy leaves the water.|물에서 에너지가 나가요.'],['Liquid water at a surface becomes vapor.|표면의 액체 물이 수증기가 돼요.','Evaporation|증발','Water absorbs energy to become vapor.|물은 에너지를 받아 수증기가 돼요.'],['Water vapor cools and becomes liquid droplets.|수증기가 식어서 물방울이 돼요.','Condensation|응결','Water releases energy as it condenses.|물은 응결하며 에너지를 내보내요.'],['A heated ice cube turns into a puddle.|데운 얼음 조각이 물웅덩이로 변해요.','Melting|녹음','The solid absorbs energy.|고체가 에너지를 받아요.'],['A tray of water cools into solid cubes.|틀의 물이 식어서 단단한 조각이 돼요.','Freezing|얼음으로 굳음','The liquid loses energy.|액체가 에너지를 잃어요.'],['A wet cloth dries as liquid water enters the air as gas.|젖은 천이 마르며 액체 물이 기체로 공기에 들어가요.','Evaporation|증발','Energy helps liquid change to gas.|에너지가 액체를 기체로 바꾸는 데 쓰여요.'],['Vapor meets a cold surface and forms droplets.|수증기가 차가운 표면에서 물방울이 돼요.','Condensation|응결','Gas changes to liquid and releases energy.|기체가 액체로 변하며 에너지를 내보내요.'],['Snow warms and turns into liquid water.|눈이 데워져 액체 물이 돼요.','Melting|녹음','Energy enters the solid water.|고체 물에 에너지가 들어와요.'],['Water on a cold path turns to ice.|차가운 길 위의 물이 얼음이 돼요.','Freezing|얼음으로 굳음','Water loses energy during freezing.|물이 얼면서 에너지를 잃어요.']];
reg('waterstate4','Water and Energy','물과 에너지','S4E3.a',(i,lv)=>{const r=changes[i].map(b),cats=['Melting|녹음','Freezing|얼음으로 굳음','Evaporation|증발','Condensation|응결'].map(b);return lv===1?q(B('Identify the state change.','상태 변화를 골라요.'),r[0],r[1],cats.filter(x=>x.en!==r[1].en).slice(0,2)):q(B('Explain energy flow for this observed change.','관찰한 변화에서 에너지의 방향을 설명해요.'),B(`Compare before and after: ${r[0].en}`,`변화 전후를 비교해요: ${r[0].ko}`),r[2],[b(r[1].en==='Melting'||r[1].en==='Evaporation'?'Energy leaves the water.|물에서 에너지가 나가요.':'Energy enters the water.|물에 에너지가 들어와요.'),b('No state change occurs.|상태 변화가 없어요.')]);});
const routes=[['Puddle → vapor|물웅덩이 → 수증기','Evaporation|증발'],['Ocean → vapor|바다 → 수증기','Evaporation|증발'],['Lake → vapor|호수 → 수증기','Evaporation|증발'],['Vapor → cloud droplets|수증기 → 구름 물방울','Condensation|응결'],['Vapor → cold-window droplets|수증기 → 차가운 창문의 물방울','Condensation|응결'],['Cloud droplets → rain|구름 물방울 → 비','Precipitation|강수'],['Cloud ice crystals → snowfall|구름 얼음 결정 → 눈','Precipitation|강수'],['Rain → water in soil|비 → 땅속의 물','Infiltration|땅으로 스며듦'],['Rain → stream along surface|비 → 지표를 따라 흐르는 시내','Runoff|지표를 따라 흐름'],['Groundwater → stream|지하수 → 시내','Groundwater flow|지하수의 흐름']];
const paths2=[['Rain soaks into soil, then enters groundwater.|비가 땅으로 스며든 뒤 지하수가 돼요.','Infiltration can lead to groundwater.|스며든 물은 지하수가 될 수 있어요.'],['Rain runs into a stream, then reaches a lake.|비가 시내로 흐른 뒤 호수에 들어가요.','Surface runoff can reach a lake.|지표를 흐른 물은 호수에 이를 수 있어요.'],['Ocean water evaporates, condenses, then falls as rain.|바닷물이 증발하고 응결한 뒤 비로 내려요.','Evaporation and condensation precede this rain.|이 경로에서는 비가 오기 전에 증발과 응결이 있어요.'],['A cloud drops snow that remains frozen for a while.|구름에서 내린 눈이 한동안 얼어 있어요.','Water can be stored as ice.|물이 얼음으로 머물 수 있어요.'],['Rain remains in a puddle, then evaporates.|비가 웅덩이에 머물다가 증발해요.','Not all rain immediately enters a river.|모든 비가 곧바로 강에 들어가지는 않아요.'],['Groundwater emerges into a stream.|지하수가 시내로 나와요.','Water can return from underground to the surface.|물이 땅속에서 지표로 돌아올 수 있어요.'],['A leaf releases water vapor that later condenses.|잎에서 나온 수증기가 나중에 응결해요.','Plants can be part of a water pathway.|식물도 물이 가는 길에 포함돼요.'],['Snow melts and the water flows into soil.|눈이 녹은 물이 땅속으로 들어가요.','Melting can be followed by infiltration.|녹은 뒤에 땅속으로 스며들 수 있어요.'],['A lake receives rain and also loses water by evaporation.|호수는 비를 받고 증발로 물을 잃기도 해요.','Water may enter and leave the same store.|같은 곳에 물이 들어오기도 하고 나가기도 해요.'],['Two raindrops take different paths: soil and stream.|빗방울 두 개가 땅속과 시내라는 다른 길로 가요.','The cycle has multiple possible routes.|물순환에는 여러 길이 있어요.']];
reg('watercycle4','Many Water Pathways','물의 여러 길','S4E3.b',(i,lv)=>{if(lv===2){const r=paths2[i].map(b);return q(B('Which conclusion fits this pathway model?','물의 경로 모형에 맞는 결론을 골라요.'),r[0],r[1],[b(['Water goes straight from rain to a stream.|비가 바로 시내로 가요.','The water first becomes groundwater.|물이 먼저 지하수가 돼요.','Rain occurs before condensation here.|여기서는 응결 전에 비가 와요.','Snow cannot be stored between stages.|눈은 단계 사이에 머물 수 없어요.','All this rain enters a river immediately.|이 비는 모두 바로 강으로 가요.','Groundwater cannot reach the surface.|지하수는 지표로 나올 수 없어요.','The leaf takes vapor from the air.|잎은 공기에서 수증기를 받아요.','Infiltration occurs before the snow changes state.|눈의 상태가 바뀌기 전에 스며들어요.','A lake can receive water but cannot lose it.|호수에는 물이 들어오기만 하고 나가지 않아요.','The two drops must use the same first path.|두 빗방울의 첫 경로가 같아요.'][i]),b(['Water first evaporates into a cloud.|물이 먼저 증발해 구름이 돼요.','The route does not reach a lake.|이 경로는 호수에 이르지 않아요.','Water remains liquid throughout this path.|이 경로 내내 물은 액체예요.','Snow melts before it can be stored.|눈은 저장되기 전에 녹아요.','The puddle must freeze before water can evaporate.|웅덩이는 얼어야 증발할 수 있어요.','Surface water flows over rather than into the soil.|지표의 물은 흙에 스며들지 않고 위로 흘러요.','The leaf absorbs the vapor rather than releasing it.|잎은 수증기를 내보내지 않고 흡수해요.','Meltwater flows across the soil instead of entering it.|녹은 물이 땅속에 들어가지 않고 표면을 흘러요.','Evaporation replaces the need for incoming water.|증발이 유입될 물을 대신해요.','The second drop must first reach the ocean.|두 번째 물방울은 먼저 바다로 가야 해요.'][i])]);}const r=routes[i].map(b),w=[...new Set(routes.filter(x=>x[1]!==routes[i][1]).map(x=>x[1]))].slice(0,2).map(b);return q(B('Name the process on this arrow.','화살표의 과정 이름을 골라요.'),r[0],r[1],w);});
const weatherTools=[['Air temperature|기온','Thermometer|온도계','°C|섭씨 도'],['Rainfall depth|강수량의 깊이','Rain gauge|우량계','mm|밀리미터'],['Air pressure|기압','Barometer|기압계','hPa|헥토파스칼'],['Wind direction|풍향','Wind vane|풍향계','Compass direction|동서남북 방향'],['Wind speed|풍속','Anemometer|풍속계','m/s|초당 미터']];
reg('weatherinstrument4','Measure the Weather','날씨 측정','S4E4.a',(i,lv)=>{const j=i%5,r=weatherTools[j].map(b);if(lv===1){const quantity=i>=5;return q(B(quantity?'Which quantity does this instrument record?':'Choose the tool for this measurement.',quantity?'도구가 기록하는 측정량을 골라요.':'측정량에 맞는 도구를 골라요.'),quantity?B(`${r[1].en}: records ${r[2].en}.`,`${r[1].ko}: 기록 단위는 ${r[2].ko}.`):r[0],quantity?r[0]:r[1],[b(weatherTools[(j+1)%5][quantity?0:1]),b(weatherTools[(j+2)%5][quantity?0:1])]);}if(i<5)return q(B('Choose the matching tool and unit.','측정량에 맞는 도구와 단위를 골라요.'),r[0],B(`${r[1].en} · ${r[2].en}`,`${r[1].ko} · ${r[2].ko}`),[B(`${r[1].en} · ${weatherTools[(j+1)%5][2].split('|')[0]}`,`${r[1].ko} · ${weatherTools[(j+1)%5][2].split('|')[1]}`),B(`${weatherTools[(j+1)%5][1].split('|')[0]} · ${r[2].en}`,`${weatherTools[(j+1)%5][1].split('|')[1]} · ${r[2].ko}`)]);const rows=[['Practice thermometer: 16°C → 20°C.|가상 온도계: 16℃ → 20℃.','Temperature rose 4°C|기온이 4℃ 올랐어요','Temperature fell 4°C|기온이 4℃ 내렸어요','Pressure rose 4 hPa|기압이 4만큼 올랐어요'],['Practice rain gauge: cumulative depth 3 → 7 mm, no spill or evaporation.|가상 우량계: 누적 깊이 3 → 7mm. 흘림과 증발은 없어요.','Additional rainfall was 4 mm|더 내린 비는 4mm예요','Additional rainfall was 10 mm|더 내린 비는 10mm예요','Wind speed rose 4 m/s|풍속이 4만큼 올랐어요'],['Practice barometer: 1008 → 1002 hPa.|가상 기압계: 1008 → 1002헥토파스칼.','Pressure fell 6 hPa|기압이 6헥토파스칼 내렸어요','Pressure rose 6 hPa|기압이 6헥토파스칼 올랐어요','This measures rainfall depth|강수량의 깊이를 잰 값이에요'],['Practice wind vane: wind from north → from south.|가상 풍향계: 북쪽에서 오던 바람 → 남쪽에서 오는 바람.','Direction changed; speed is not measured|방향 변화; 속도는 몰라요','Speed doubled|속도가 두 배예요','The vane records air pressure|풍향계는 기압을 기록해요'],['Practice anemometer: 2 → 5 m/s.|가상 풍속계: 초당 2 → 5미터.','Speed increased by 3 m/s|풍속이 초당 3미터 늘었어요','Direction changed by 3 degrees|방향이 3도 바뀌었어요','Speed fell by 3 m/s|풍속이 초당 3미터 줄었어요']][j].map(b);return q(B('Interpret this instrument record.','도구의 관측 기록을 읽어요.'),rows[0],rows[1],rows.slice(2));});
const fronts=[['Cold front: triangles toward the warm air|한랭전선: 따뜻한 공기 쪽으로 향한 삼각형','Colder air advances|찬 공기가 나아가요'],['Warm front: semicircles toward the cold air|온난전선: 찬 공기 쪽으로 향한 반원','Warmer air advances|따뜻한 공기가 나아가요'],['Stationary front: triangles and semicircles on opposite sides|정체전선: 반대쪽의 삼각형과 반원','Neither air mass advances|어느 쪽도 밀어내지 못해요']];
reg('weathermap4','Weather Map Evidence','날씨 지도 예측','S4E4.b',(i,lv)=>{const f=fronts[i%3].map(b),t=10+i*2,pressure=1005+i,rain=i%2===0;return q(B(lv===1?'Use the legend to interpret the boundary.':'Use the front and observations. Which cautious forecast fits?',lv===1?'범례로 공기 경계를 읽어요.':'전선과 관측을 보고 조심스럽게 예측해요.'),B(`Practice station ${i+1}: ${t}°C, ${pressure} hPa, ${rain?'rain nearby':'no rain observed'}. ${f[0].en}.`,`가상 관측소 ${i+1}: ${t}℃, 기압 ${pressure}헥토파스칼, ${rain?'주변에 비':'관측된 비 없음'}. ${f[0].ko}.`),lv===1?f[1]:b(i%3===0?'Temperature may fall as colder air arrives|찬 공기가 오면 기온이 내려갈 수 있어요':i%3===1?'Temperature may rise as warmer air arrives|따뜻한 공기가 오면 기온이 올라갈 수 있어요':'The boundary may linger; collect more observations|경계가 머물 수 있으니 관측을 더 해요'),lv===1?fronts.filter((_,j)=>j!==i%3).map(x=>b(x[1])):[b(i%3===0?'Warmer air may raise the temperature|따뜻한 공기로 기온이 올라갈 수 있어요':i%3===1?'Colder air may lower the temperature|찬 공기로 기온이 내려갈 수 있어요':'The boundary moves rapidly eastward|경계가 동쪽으로 빠르게 움직여요'),b(i%3===2?'Both air masses move forward together|두 공기가 함께 앞으로 나아가요':'The front has stopped moving|전선이 움직임을 멈췄어요')]);});
const cloudRows=[['High thin wisps|높고 가느다란 결','Cirrus|권운'],['Low gray sheet|낮은 회색 층','Stratus|층운'],['Puffy heaps with flatter bases|아래가 비교적 평평한 뭉게 모양','Cumulus|적운'],['High feather-like streaks|높은 깃털 같은 줄','Cirrus|권운'],['Broad low blanket|낮고 넓은 담요 모양','Stratus|층운'],['Separate cotton-like puffs|따로 있는 솜뭉치 모양','Cumulus|적운'],['Thin high ice-crystal cloud|높고 얇은 얼음 결정 구름','Cirrus|권운'],['Low uniform layer across the sky|하늘에 넓게 이어진 낮고 고른 층','Stratus|층운'],['Growing lumpy white cloud|뭉게뭉게 자라는 흰 구름','Cumulus|적운'],['A flat cloud layer near the ground|지표 가까이 평평하게 이어진 구름 층','Stratus|층운']];
reg('cloud4','Clouds and Observations','구름과 관측','S4E4.c',(i,lv)=>{const r=cloudRows[i].map(b),cats=['Cirrus|권운','Stratus|층운','Cumulus|적운'].map(b);return lv===1?q(B('Which cloud category fits the described observation?','설명한 관찰에 맞는 구름 종류를 골라요.'),r[0],r[1],cats.filter(x=>x.en!==r[1].en)):q(B('Choose a justified next weather investigation.','근거 있는 다음 날씨 조사 방법을 골라요.'),B(`Station ${i+1}: ${r[0].en}; ${i%2?'pressure falling':'pressure steady'}. No measured rainfall yet.`,`관측소 ${i+1}: ${r[0].ko}; 기압 ${i%2?'하강':'유지'}. 아직 강수량은 측정하지 않았어요.`),b(i%2?'Check pressure, cloud change, and rainfall again|기압과 구름 변화, 강수량을 다시 살펴요':'Keep a dated record and compare later conditions|날짜 있는 기록을 남기고 나중에 비교해요'),[b('Use this cloud alone to set tomorrow’s rainfall amount|이 구름만 보고 내일 강수량을 정해요'),b('Record cloud type but skip pressure and rainfall changes|구름 종류만 적고 기압과 강수 변화는 조사하지 않아요')]);});
reg('climate4','Weather and Climate','날씨와 기후','S4E4.d',(i,lv)=>{const long=i%2===0,n=long?30+i:1,places=['coast|해안','mountains|산지','town|마을','valley|계곡','plain|평야'][Math.floor(i/2)],data=B(`${b(places).en}: ${long?`${n} years of seasonal records`:'today\'s temperature and rain'}.`,`${b(places).ko}: ${long?`${n}년 동안의 계절별 기록`:'오늘 기온과 비 기록'}.`);return lv===1?q(B('Does this record describe weather or climate?','이 기록은 날씨와 기후 중 무엇을 설명할까요?'),data,b(long?'Climate|기후':'Weather|날씨'),[b(long?'Weather|날씨':'Climate|기후'),b('Landform|지형')]):q(B('Which conclusion is justified by this record?','기록으로 뒷받침되는 결론을 골라요.'),data,b(long?'We can examine long-term seasonal patterns|오랜 계절별 경향을 살펴볼 수 있어요':'We know this day, not the long-term pattern|이날을 알 뿐 오랜 경향은 몰라요'),[b(long?'It describes a single day rather than a seasonal pattern|계절 경향보다 하루를 설명해요':'This day gives the seasonal average|이 하루가 계절 평균을 알려 줘요'),b('Weather and climate mean the same thing|날씨와 기후는 같은 뜻이에요')]);});
